<?php
namespace App\Services;
use Illuminate\Support\Facades\DB;
use RuntimeException;
class CheckoutService {
 public function calculate(array $items,float $shipping=0,float $discount=0,float $wallet=0):array{$subtotal=collect($items)->sum(fn($i)=>(float)$i['price']*(int)$i['quantity']);$wallet=min(max(0,$wallet),max(0,$subtotal+$shipping-$discount));return compact('subtotal','shipping','discount','wallet')+['total'=>max(0,$subtotal+$shipping-$discount-$wallet)];}
 public function createOrder(int $userId,array $items,array $totals,string $type='retail',?string $shippingAddress=null):int{return DB::transaction(function()use($userId,$items,$totals,$type,$shippingAddress){if(!$items)throw new RuntimeException('Cart is empty.');$number='CP-'.now()->format('YmdHis').'-'.random_int(100,999);$orderId=DB::table('orders')->insertGetId(['order_number'=>$number,'user_id'=>$userId,'order_type'=>in_array($type,['retail','wholesale','group_buy'],true)?$type:'retail','status'=>'pending','subtotal'=>$totals['subtotal'],'shipping_amount'=>$totals['shipping'],'discount_amount'=>$totals['discount'],'wallet_amount'=>$totals['wallet']??0,'total_amount'=>$totals['total'],'currency'=>config('chacha.brand.default_currency','USD'),'placed_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);foreach($items as $item)DB::table('order_items')->insert(['order_id'=>$orderId,'product_id'=>$item['product_id'],'variant_id'=>$item['variant_id']??$item['variation_id']??null,'sku'=>$item['sku']??'','product_title'=>$item['title']??$item['product_title']??'Product','quantity'=>(int)$item['quantity'],'unit_price'=>(float)$item['price'],'total_price'=>(float)$item['price']*(int)$item['quantity'],'created_at'=>now()]);DB::table('order_status_history')->insert(['order_id'=>$orderId,'status'=>'pending','note'=>'Order created.','created_by'=>$userId,'created_at'=>now()]);return $orderId;});}
}